(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-795":{scenario:{company:"Công ty Dịch vụ Mặt đất Cánh Diều",supervisor:{name:"Lê Hoàng Phúc",role:{vi:"Trưởng ca Phục vụ hành khách",en:"Passenger Services Duty Manager"}},ref_code:"PS-8364",title:{vi:"Đúng hàng nguy hiểm. Đúng cước hành lý. Bay an toàn.",en:"Right dangerous goods call. Right baggage fee. Safe flight."},brief:{vi:"Bạn làm thủ tục chuyến bay quốc tế mô phỏng: hành khách hạng phổ thông, thẻ hội viên hạng Bạc, ký gửi 2 kiện 24 kg và 17 kg; trong vali có pin sạc dự phòng ghi 20000 mAh, 3.7 V. Tiêu chuẩn hành lý ký gửi 23 kg, hội viên hạng Bạc được thêm 10 kg, phí quá cước 220.000 đồng/kg (số liệu mô phỏng). Hồ sơ nháp PS-8364 đang ghi sai phương án vận chuyển pin sạc và phí quá cước. Sửa hai trường rồi lập báo cáo có căn cứ.",en:"You are checking in a simulated international flight: an economy passenger with a Silver loyalty card checks 2 bags of 24 kg and 17 kg; the suitcase holds a power bank marked 20000 mAh, 3.7 V. Checked allowance is 23 kg, Silver members get 10 kg extra, excess fee 220,000 VND per kg (training figures). Draft record PS-8364 has the wrong power bank carriage and excess fee. Correct both fields and write an evidence-based report."},reference_title:{vi:"Quy định hàng nguy hiểm & biểu phí hành lý đã duyệt · PS-8364",en:"Approved dangerous goods rules & baggage tariff · PS-8364"},fields:[{id:"POWERBANK",label:{vi:"Phương án vận chuyển pin sạc dự phòng",en:"Power bank carriage"},initial:"CHECKED",expected:"CABIN",choices:["CHECKED","CABIN","FORBIDDEN"],reference:"Bảng quy định hàng nguy hiểm cho hành khách",hint:{vi:"Pin sạc dự phòng lithium bị cấm trong hành lý ký gửi; tính Wh để biết có được xách tay mà không cần phê duyệt.",en:"Lithium power banks are banned from checked baggage; compute Wh to see if cabin carriage needs approval."}},{id:"EXCESS_FEE",label:{vi:"Phí quá cước hành lý (VND)",en:"Excess baggage fee (VND)"},initial:"3960000",expected:"1760000",reference:"Biểu phí hành lý quá cước",ref_value:{vi:"Kiện 24 kg + 17 kg; tiêu chuẩn 23 kg; hội viên Bạc thêm 10 kg; 220.000 đồng/kg (mô phỏng)",en:"Bags 24 kg + 17 kg; allowance 23 kg; Silver extra 10 kg; 220,000 VND per kg (training)"},hint:{vi:"Cộng tiêu chuẩn của hội viên vào tiêu chuẩn hạng vé trước khi tính số kg vượt.",en:"Add the loyalty allowance to the fare allowance before computing the excess kilograms."}}],sop32:{vi:"Phí quá cước = (tổng trọng lượng ký gửi - tiêu chuẩn hạng vé - tiêu chuẩn cộng thêm của hội viên) x đơn giá/kg; mỗi kiện không quá 32 kg; năng lượng pin Wh = mAh x V / 1000 (số liệu mô phỏng).",en:"Excess fee = (total checked weight - fare allowance - loyalty extra allowance) x rate per kg; no bag over 32 kg; battery energy Wh = mAh x V / 1000 (training figures)."},context:{label:"DCS / PS-8364",metrics:[{label:{vi:"Hành lý ký gửi",en:"Checked bags"},value:"24 + 17 kg"},{label:{vi:"Tiêu chuẩn",en:"Allowance"},value:"23 + 10 kg"},{label:{vi:"Pin sạc dự phòng",en:"Power bank"},value:"20000 mAh / 3.7 V"}]},crisis:{vi:"Hành khách là người quen của một trưởng ca khác. Người này nhắn bạn: “Ghi tổng 33 kg cho khách để khỏi thu phí, còn cục sạc cứ để trong vali, máy soi ít khi phát hiện.”",en:"The passenger knows another duty manager, who messages you: “Enter 33 kg in total so there's no fee, and leave the power bank in the suitcase, screening rarely catches it.”"},options:{safe:{vi:"Ghi đúng cân thực tế, thu phí theo quy định, yêu cầu khách chuyển pin sạc sang hành lý xách tay; miễn giảm chỉ khi có phê duyệt trên hệ thống và báo trưởng ca phụ trách.",en:"Record the true weight, charge per tariff and have the power bank moved to cabin baggage; waivers only with system approval, and inform the duty manager in charge."},shortcut:{vi:"Ghi 33 kg như được nhắn và để pin sạc trong vali ký gửi cho nhanh.",en:"Enter 33 kg as asked and leave the power bank in the checked suitcase to save time."},wait:{vi:"Giữ hành lý ở quầy, không làm gì và chờ trưởng ca kia tự đến xử lý.",en:"Hold the bags at the counter, do nothing and wait for the other manager to come."}},questions:{vi:["Vì sao bạn đổi phương án vận chuyển pin sạc dự phòng? Phép tính Wh nào chứng minh lựa chọn đó?","Trình bày cách tính phí quá cước và cách xử lý khi có người yêu cầu ghi sai trọng lượng hành lý."],en:["Why did you change the power bank carriage? Which Wh calculation supports your choice?","Explain how you calculated the excess fee and how you handle a request to record a false baggage weight."]},hints:{vi:["Quy đổi dung lượng pin sang Wh rồi so với các ngưỡng trong bảng hàng nguy hiểm cho hành khách.","Theo SOP mục 3.2: xác định tổng tiêu chuẩn được hưởng trước khi trừ khỏi tổng trọng lượng.","Đọc lại SOP mục 4.2: trọng lượng và hàng nguy hiểm phải khai đúng, mọi miễn giảm cần phê duyệt."],en:["Convert the battery capacity to Wh and compare it with the passenger dangerous goods thresholds.","Per SOP 3.2: work out the total allowance before subtracting it from the total weight.","Re-read SOP 4.2: weight and dangerous goods must be declared truthfully; waivers need approval."]}},learning:{summary:{vi:"Nhân viên phục vụ mặt đất và thủ tục hàng không làm thủ tục cho hành khách, kiểm tra giấy tờ đi lại, chấp nhận hành lý, nhận diện hàng nguy hiểm, thu phí dịch vụ, điều phối lên tàu bay và hỗ trợ hành khách cần trợ giúp đặc biệt. Công việc ảnh hưởng trực tiếp đến an toàn bay, đúng giờ khai thác và trải nghiệm khách. Nghề đòi hỏi thao tác hệ thống nhanh, ngoại ngữ, kiến thức quy định quốc tế và bản lĩnh giữ nguyên tắc trước áp lực.",en:"An airport ground handling and passenger service agent checks in passengers, verifies travel documents, accepts baggage, identifies dangerous goods, collects service fees, runs boarding and assists passengers needing special help. The work directly affects flight safety, on-time performance and passenger experience. The role needs fast system skills, languages, knowledge of international rules and the firmness to hold to procedure under pressure."},responsibilities:{vi:["Làm thủ tục, kiểm tra hộ chiếu, thị thực và điều kiện nhập cảnh của điểm đến.","Chấp nhận hành lý, cân, dán thẻ, thu phí quá cước theo biểu phí của hãng.","Hỏi và nhận diện hàng nguy hiểm, hướng dẫn hành khách xử lý pin lithium, chất lỏng.","Điều phối cửa ra tàu bay, đối chiếu số khách và đóng chuyến đúng giờ.","Hỗ trợ hành khách cần trợ giúp đặc biệt, xử lý chậm, hủy chuyến và hành lý thất lạc."],en:["Check in passengers and verify passports, visas and destination entry rules.","Accept, weigh and tag baggage and collect excess fees per the airline tariff.","Ask about and identify dangerous goods and guide passengers on lithium batteries and liquids.","Run the boarding gate, reconcile passenger counts and close the flight on time.","Assist passengers with reduced mobility and handle delays, cancellations and mishandled bags."]},competencies:[{name:{vi:"Nhận diện hàng nguy hiểm",en:"Dangerous goods awareness"},desc:{vi:"Hỏi đúng câu hỏi, tính Wh của pin và áp ngưỡng cho phép, cấm, cần phê duyệt.",en:"Ask the right questions, compute battery Wh and apply allowed, forbidden and approval thresholds."}},{name:{vi:"Chấp nhận hành lý",en:"Baggage acceptance"},desc:{vi:"Tính đúng tiêu chuẩn, phí quá cước, giới hạn kiện và dán thẻ đúng điểm đến.",en:"Apply allowances, excess fees and piece limits correctly and tag to the right destination."}},{name:{vi:"Kiểm tra giấy tờ đi lại",en:"Travel document checks"},desc:{vi:"Đối chiếu hạn hộ chiếu, thị thực, điều kiện nhập cảnh trước khi cấp thẻ lên tàu.",en:"Check passport validity, visas and entry conditions before issuing a boarding pass."}},{name:{vi:"Giao tiếp dưới áp lực",en:"Communication under pressure"},desc:{vi:"Giải thích quy định rõ ràng, lịch sự với hành khách khó tính và giữ hàng chờ thông suốt.",en:"Explain rules clearly and politely to difficult passengers and keep the queue moving."}},{name:{vi:"Tuân thủ an toàn, an ninh",en:"Safety and security compliance"},desc:{vi:"Từ chối ghi sai trọng lượng, không nhận hộ hành lý và báo ngay dấu hiệu bất thường.",en:"Refuse false weights, never accept bags for others and report anything unusual at once."}}],knowledge:{vi:["Phụ lục 18 Công ước Chicago và Hướng dẫn kỹ thuật ICAO Doc 9284 về vận chuyển an toàn hàng nguy hiểm bằng đường hàng không.","Quy định hàng nguy hiểm IATA (DGR) cho hành khách: pin lithium, pin sạc dự phòng, ngưỡng 100 Wh và 160 Wh.","Luật Hàng không dân dụng Việt Nam năm 2006, sửa đổi, bổ sung năm 2014.","Công ước Montreal 1999 về trách nhiệm của người vận chuyển đối với hành khách và hành lý.","Quy định hiện hành về an ninh hàng không và kiểm tra giấy tờ đi lại tại sân bay."],en:["Annex 18 to the Chicago Convention and ICAO Doc 9284 Technical Instructions on the safe transport of dangerous goods by air.","IATA Dangerous Goods Regulations for passengers: lithium batteries, power banks, the 100 Wh and 160 Wh thresholds.","Vietnam Civil Aviation Law of 2006, amended in 2014.","Montreal Convention 1999 on carrier liability for passengers and baggage.","Current aviation security rules and travel document checks at airports."]},tools:["Hệ thống kiểm soát khởi hành (DCS)","Cân và băng chuyền hành lý","Máy in thẻ lên tàu và thẻ hành lý","Hệ thống tra cứu điều kiện nhập cảnh","Hệ thống truy tìm hành lý thất lạc"],kpis:{vi:["Thời gian chờ làm thủ tục trung bình của hành khách.","Tỷ lệ đóng cửa lên tàu bay đúng giờ.","Số hành lý thất lạc hoặc dán sai thẻ trên 1000 hành khách.","Số vụ hàng nguy hiểm bị phát hiện sau quầy thủ tục (mục tiêu bằng 0)."],en:["Average passenger check-in waiting time.","Share of boarding gates closed on time.","Mishandled or mistagged bags per 1000 passengers.","Dangerous goods cases found after check-in (target zero)."]},day:[{time:"04:30",vi:"Nhận ca, nghe briefing về chuyến bay, khách đặc biệt và thông báo an toàn mới.",en:"Start the shift with a briefing on flights, special passengers and new safety notices."},{time:"05:00",vi:"Mở quầy thủ tục, kiểm tra giấy tờ và chấp nhận hành lý chuyến sáng.",en:"Open check-in, verify documents and accept baggage for the morning flight."},{time:"07:30",vi:"Điều phối cửa ra tàu bay, đối chiếu số khách và đóng chuyến.",en:"Run the boarding gate, reconcile passenger numbers and close the flight."},{time:"10:00",vi:"Xử lý chuyến chậm: thông báo cho khách, sắp xếp suất ăn và đổi chuyến.",en:"Handle a delayed flight: inform passengers, arrange meals and rebook."},{time:"12:30",vi:"Lập báo cáo ca, ghi nhận sự cố hàng nguy hiểm và bàn giao quầy.",en:"Write the shift report, log dangerous goods events and hand over the counter."}],mistakes:{vi:["Để pin sạc dự phòng trong hành lý ký gửi vì không hỏi kỹ hành khách.","Quên cộng tiêu chuẩn hành lý của hội viên nên thu phí quá cước sai.","Không kiểm tra hạn hộ chiếu, thị thực khiến khách bị từ chối nhập cảnh ở điểm đến."],en:["Leaving a power bank in checked baggage because the passenger was not asked properly.","Forgetting the loyalty allowance and charging the wrong excess fee.","Not checking passport or visa validity so the passenger is refused entry at destination."]},career:[{vi:"Nhân viên thủ tục hàng không",en:"Check-in agent"},{vi:"Nhân viên phục vụ hành khách chính, giám sát cửa ra tàu bay",en:"Senior passenger service and gate agent"},{vi:"Trưởng ca Phục vụ hành khách",en:"Passenger services duty manager"},{vi:"Quản lý dịch vụ mặt đất tại sân bay",en:"Airport ground services manager"}],glossary:[{term:"DCS",vi:"Hệ thống kiểm soát khởi hành dùng để làm thủ tục, chấp nhận hành lý và đóng chuyến.",en:"Departure control system for check-in, baggage acceptance and flight closing."},{term:"Wh",vi:"Oát giờ, đơn vị năng lượng của pin, bằng mAh nhân điện áp chia 1000.",en:"Watt-hour, a battery energy unit equal to mAh times voltage divided by 1000."},{term:"Excess baggage",vi:"Hành lý vượt tiêu chuẩn miễn cước, phải trả phí theo biểu phí của hãng.",en:"Baggage above the free allowance, charged per the airline tariff."},{term:"PRM",vi:"Hành khách hạn chế khả năng di chuyển, cần hỗ trợ như xe lăn, người dẫn.",en:"Passenger with reduced mobility who needs help such as a wheelchair or escort."},{term:"Offload",vi:"Đưa hành khách hoặc hành lý ra khỏi chuyến bay khi không đủ điều kiện vận chuyển.",en:"Removing a passenger or bag from a flight when carriage conditions are not met."}],quiz:[{q:{vi:"Pin sạc dự phòng ghi 26800 mAh, 3.7 V. Theo ngưỡng IATA cho hành khách, phương án đúng là gì?",en:"A power bank is marked 26800 mAh, 3.7 V. Under IATA passenger thresholds, what is correct?"},options:{vi:["Cấm vận chuyển","Được ký gửi","Xách tay, không cần phê duyệt","Xách tay, cần hãng phê duyệt"],en:["Forbidden","May be checked","Cabin only, no approval needed","Cabin only, airline approval needed"]},answer:2,explain:{vi:"26800 x 3.7 / 1000 = 99.16 Wh, không quá 100 Wh nên được xách tay mà không cần phê duyệt; không được ký gửi.",en:"26800 x 3.7 / 1000 = 99.16 Wh, not above 100 Wh, so cabin carriage needs no approval; never checked."}},{q:{vi:"Pin lithium dự phòng ở mức năng lượng nào cần hãng hàng không phê duyệt?",en:"At what energy level does a spare lithium battery need airline approval?"},options:{vi:["Từ 50 đến 100 Wh","Trên 100 đến 160 Wh","Trên 160 Wh","Mọi mức năng lượng"],en:["50 to 100 Wh","Above 100 up to 160 Wh","Above 160 Wh","Any energy level"]},answer:1,explain:{vi:"Trên 100 Wh đến 160 Wh cần phê duyệt của hãng; trên 160 Wh bị cấm với hành khách.",en:"Above 100 Wh up to 160 Wh needs airline approval; above 160 Wh is forbidden for passengers."}},{q:{vi:"Một kiện hành lý ký gửi nặng 35 kg. Bạn xử lý thế nào?",en:"A checked bag weighs 35 kg. What do you do?"},options:{vi:["Dán thẻ nặng và nhận bình thường","Thu thêm phí rồi nhận","Nhờ nhân viên bốc xếp tự xử lý","Đề nghị khách chia lại hành lý vì vượt giới hạn kiện"],en:["Add a heavy tag and accept it","Charge extra and accept it","Let the loaders deal with it","Ask the passenger to repack because it exceeds the piece limit"]},answer:3,explain:{vi:"Giới hạn 32 kg mỗi kiện bảo vệ an toàn lao động cho nhân viên bốc xếp; kiện nặng hơn phải chia lại.",en:"The 32 kg piece limit protects baggage handlers; heavier bags must be repacked."}},{q:{vi:"Một người lạ ở sảnh nhờ hành khách ký gửi hộ một túi quà. Hành khách hỏi ý kiến bạn. Bạn trả lời thế nào?",en:"A stranger in the hall asks a passenger to check in a gift bag for them. The passenger asks you. What do you say?"},options:{vi:["Không nhận hộ hành lý của người khác và báo an ninh","Nhận nếu túi nhẹ","Mở túi xem rồi nhận","Nhận nếu người lạ để lại số điện thoại"],en:["Do not carry others' bags and inform security","Accept it if it is light","Open it, check, then accept","Accept it if the stranger leaves a phone number"]},answer:0,explain:{vi:"Hành khách phải tự đóng gói và chịu trách nhiệm hành lý; nhận hộ người lạ là rủi ro an ninh nghiêm trọng.",en:"Passengers must pack and own their baggage; carrying bags for strangers is a serious security risk."}}],tools_en:["Departure control system (DCS)","Baggage scales and conveyors","Boarding pass and bag tag printers","Entry requirements lookup system","Lost baggage tracing system"]}}})})(window.KKR);
